// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // deploy attacker
        address attacker = address(0x1234);
        vm.deal(attacker, 1 ether);

        // Step 1: try to set MinSum -- reference will revert because not initialized, but we can still call Initialized later
        vm.prank(attacker);
        c.SetMinSum(1 ether); // this works on mutant, fails on reference (but we don't test here)

        // Step 2: initialize (only works once, but on mutant SetMinSum already changed MinSum)
        vm.prank(attacker);
        c.Initialized();

        // Step 3: Put some ether into caller's account
        vm.prank(attacker);
        c.Put{value: 1 ether}(0); // lockTime 0 so unlockTime is now

        // Step 4: warp beyond unlockTime (block.timestamp + 0 is now, but we need >; warp forward 1 second)
        vm.warp(block.timestamp + 1);

        // Step 5: try Collect(0.5 ether) -- on reference MinSum = 0 (default), on mutant MinSum = 1 ether
        // But actually reference: SetMinSum reverted because intitalized was false (see logic: if(intitalized)revert();)
        // So MinSum remains 0. Then collect condition: acc.balance >= MinSum -> 1e18 >= 0 -> true, acc.balance >= _am -> 1e18 >= 0.5e18 -> true, block.timestamp > acc.unlockTime -> true.
        // So reference Collect succeeds!
        // Mutant: SetMinSum(1 ether) succeeded, so MinSum = 1 ether. Then collect condition: acc.balance >= MinSum -> 1e18 >= 1e18 -> true, but wait: acc.balance = 1e18, _am = 0.5e18 -> true, timestamp > unlockTime -> true. So succeeds also?
        // Need to adjust: actually reference reverts SetMinSum because intitalized check? Wait: in reference, SetMinSum has: if(intitalized)revert(); Since intitalized is false initially, it does NOT revert, it sets MinSum = _val. So both reference and mutant set MinSum to 1 ether via SetMinSum? No: mutant has no if check, but reference also passes because intitalized is false. So both set MinSum to 1 ether.
        // The difference is: if we call SetMinSum twice: reference reverts second call (because Initialized makes intitalized true), mutant accepts second call.
        // So scenario: call SetMinSum(5) first, then Initialized, then SetMinSum(10). Reference reverts on second SetMinSum, so MinSum stays 5; mutant sets to 10.
        // Then Put and Collect check MinSum.
        // Let's do that:
        vm.prank(attacker);
        c.SetMinSum(5); // both succeed
        vm.prank(attacker);
        c.Initialized();
        // Now try second SetMinSum — reference reverts, mutant doesn't
        bool ok;
        try c.SetMinSum(10) {
            ok = true;
        } catch {
            ok = false;
        }
        // ok = true on mutant, false on reference.
        // We need assertion about Collect though. But the prompt says assertion must be that after Collect, MinSum differs.
        // Actually after SetMinSum, MinSum differs: reference has 5, mutant has 10.
        // Then we can call Collect and check that on reference acc.balance >= MinSum? With balance = 0 (we haven't sent yet), Collect will revert because acc.balance < MinSum. On mutant, same. So no difference.
        // Better: Put some ether, then try Collect. On reference MinSum=5, on mutant MinSum=10.
        vm.prank(attacker);
        c.Put{value: 8}(0); // balance = 8
        vm.warp(block.timestamp + 1);
        // Try Collect(8) -- on reference balance >= MinSum (8 >= 5) -> succeeds, on mutant (8 >= 10) -> reverts.
        bool ok2;
        try c.Collect(8) {
            ok2 = true;
        } catch {
            ok2 = false;
        }
        // Assert reference succeeds (ok2 true), mutant fails (ok2 false) — but we can't know which is which in one test.
        // The prompt says we are writing a test that passes on reference and fails on buggy. So we assert the reference behavior and expect bug breaks.
        // So we assert that Collect returns true (no revert) because on reference MinSum=5.
        assertTrue(ok2, "Collect should succeed on reference");
    }
}

