pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: First call SetMinSum(1) - should set MinSum to 1 in both (no Initialized yet)
        c.SetMinSum(1);

        // Step 2: Second call SetMinSum(2) - reference reverts (intitalized check), mutant sets MinSum=2
        // In reference, MinSum stays 0 (first call also reverted? Wait, first call should succeed)
        // Actually, let's reason: initially intitalized=false, so first SetMinSum(1) succeeds for both reference and mutant.
        // Second SetMinSum(2): reference reverts (intitalized check fails because intitalized is still false? No, the check is if(intitalized) revert; intitalized is false, so it should succeed too! That's wrong.

        // Let's re-evaluate: the mutant removes the if(intitalized) revert, so SetMinSum can be called multiple times without restriction.
        // The reference has the check, but since intitalized is never set to true by calling SetMinSum, it remains false, so SetMinSum can be called multiple times in reference as well! That means no divergence here.
        // We need to call Initialized first to make SetMinSum revert in reference.

        // Correct sequence:
        // 1. Initialized() - sets intitalized=true
        c.Initialized();

        // 2. Try SetMinSum(2) - reference reverts (intitalized check), mutant succeeds (sets MinSum=2)
        // We'll catch the revert on reference, but in the test we just call it and later observe MinSum difference.
        // Since we need concrete calls, we'll call SetMinSum(2) directly - reference reverts silently (tx reverts), but in foundry test, a revert would fail the test unless we catch it.
        // To avoid test failure, we can use try/catch on Collect later, or we can skip calling SetMinSum(2) on reference and instead observe that after Initialized, SetMinSum cannot be called again.
        // Better: call SetMinSum(2) in both; in reference it reverts (test would fail), so we need to use try/catch to call it and ignore revert.

        bool secondSetMinSumSucceeded = false;
        try c.SetMinSum(2) {
            secondSetMinSumSucceeded = true;
        } catch {
            // reference reverts here
        }

        // For reference, secondSetMinSumSucceeded = false, so MinSum remains 1 (from first call)
        // For mutant, secondSetMinSumSucceeded = true, MinSum = 2

        // Now Put(0) with 1 wei
        address alice = address(0x123);
        vm.deal(alice, 1 wei);
        vm.prank(alice);
        c.Put{value: 1 wei}(0);

        // Now Collect(1 wei) - in reference, MinSum=1, balance=1, unlockTime passed? We need block.timestamp > acc.unlockTime
        // Put(0) sets unlockTime = block.timestamp + 0 = block.timestamp, so Collect requires block.timestamp > block.timestamp, which is false
        // So Collect will revert in both because unlockTime condition fails. Need to advance time.
        vm.warp(block.timestamp + 1);

        bool collectResult;
        try c.Collect(1) {
            collectResult = true;
        } catch {
            collectResult = false;
        }

        // In reference: MinSum=1, balance=1, block.timestamp > unlockTime (true), so Collect should succeed (balance>=MinSum and balance>=1)
        // Wait: unlockTime was set to block.timestamp at Put time (which was t), then we warped to t+1, so block.timestamp > unlockTime holds.
        // In reference, since second SetMinSum reverted, MinSum = 1. balance = 1, _am = 1, so Collect succeeds.
        // In mutant, second SetMinSum succeeded, MinSum = 2, balance = 1, _am = 1, but balance >= MinSum is false, so Collect reverts.
        // So divergence: reference collectResult = true, mutant collectResult = false.

        assertTrue(collectResult == true, "Collect should succeed in reference but fails in mutant");
    }
}

