    C public c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize MinSum to 123
        c.SetMinSum(123);
        c.Initialized();
        // Deploy attacker contract
        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), 1 ether);
        // Fund attacker's account in C by having them call Put
        vm.prank(address(attacker));
        c.Put{value: 1}(0);
        // Now trigger the reentrant call via Collect
        vm.prank(address(attacker));
        // This call will revert in reference due to locked guard on SetMinSum
        // In buggy version it succeeds and changes MinSum to 456
        c.Collect(1);
        // Check the divergence: reference has MinSum = 123, buggy has MinSum = 456
        assertTrue(c.MinSum() != 123);
    }
