pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testRegression_property() public {
        // Step 1: Set MinSum to 123 before initialization
        c.SetMinSum(123);

        // Step 2: Deploy attacker contract
        Attacker attacker = new Attacker(address(c));
        vm.deal(address(attacker), 1 ether);

        // Step 3: fund the attacker's account with 1 wei via Put (needs minimal balance)
        vm.prank(address(attacker));
        c.Put{value: 1 wei}(0);

        // Step 4: Call Collect(1) from attacker - this will trigger reentrancy
        // The attacker's fallback calls c.SetMinSum(456)
        vm.prank(address(attacker));
        try c.Collect(1) {
            // Collect succeeded in buggy version, may revert in reference
        } catch {
            // Collect reverted in reference due to reentrancy guard on inner SetMinSum
        }

        // Step 5: Check the value of SetMinSum
        // Reference: should be 123 (inner call reverted)
        // Bug: should be 456 (inner call succeeded)
        assertTrue(c.MinSum() == 123 || c.MinSum() == 456, "MinSum should be either 123 or 456");
        // But to specifically differentiate: reference must be 123, bug 456
        // We'll assert that it is exactly 123 for reference (passes) and 456 for bug (fails)
        // But since we don't know which version we're testing, we use the specific assertion
        // For the reference: assertTrue(c.MinSum() == 123); 
        // For the bug: assertTrue(c.MinSum() == 456);
        // The test is designed so that the reference passes and the bug fails
        if (c.MinSum() == 456) {
            assertTrue(false, "Bug detected: reentrancy allowed SetMinSum to change");
        }
        assertTrue(c.MinSum() == 123, "Reference: SetMinSum unchanged at 123");
    }
}

