        uint256 c = a + b;
        assert(c >= a);
        return c;
    }
    bool internal locked_;
    constructor() {
        locked_ = false;
    }
    modifier nonReentrant_() {
        require(!locked_);
        locked_ = true;
        _;
        locked_ = false;
    }
}

